VAR
    Overload_Timer : TON;
END_VAR

// Overload condition: Current >= 51.9 A (prompt says "not below 51.9 A", which means >= 51.9 A)
Overload_Timer(IN := Motor_Current >= 51.9, PT := T#3S);

// Set Overload_Alarm when timer expires
IF Overload_Timer.Q THEN
    Overload_Alarm := TRUE;
END_IF

// Clear alarm on rising edge of Fault_Reset
IF Fault_Reset THEN
    Overload_Alarm := FALSE;
END_IF

// Stop the motor if current remains at or above 51.9 A for more than 3 seconds
IF Overload_Timer.Q THEN
    Motor_Stop := TRUE;
END_IF

// Normal start/stop logic integration
IF Start_Command AND NOT Overload_Alarm THEN
    Motor_Stop := FALSE;
END_IF

